  .loading-shadow{
    position:absolute; bottom:26px; left:50%;
    width:78px; height:16px;
    transform:translateX(-50%) scaleX(.5);
    background:radial-gradient(ellipse at center, rgba(0,0,0,.55) 0%, rgba(0,0,0,0) 72%);
    border-radius:50%;
    animation:loadingShadowPulse 1.4s ease-in-out infinite;
    z-index:1;
  }
  @keyframes loadingShadowPulse{
    0%{ transform:translateX(-50%) scaleX(.45); opacity:.3; }
    55%{ transform:translateX(-50%) scaleX(1); opacity:.55; }
    100%{ transform:translateX(-50%) scaleX(.45); opacity:.3; }
  }
  .loading-char{
    position:absolute; bottom:30px; left:50%;
    width:118px; height:auto;
    transform:translateX(-50%) translateY(-9px);
    image-rendering:pixelated;
    transform-origin:bottom center;
    z-index:2;
    animation:loadingCharBounce 1.4s cubic-bezier(.45,0,.55,1) infinite;
    filter:drop-shadow(2px 3px 0 rgba(0,0,0,.25));
  }
  @keyframes loadingCharBounce{
    0%{   transform:translateX(-50%) translateY(-9px) scale(1,1); }
    38%{  transform:translateX(-50%) translateY(-9px) scale(1,1); }
    54%{  transform:translateX(-50%) translateY(0px) scale(1.16,.8); }
    62%{  transform:translateX(-50%) translateY(-1px) scale(.9,1.16); }
    75%{  transform:translateX(-50%) translateY(-4.8px) scale(1.02,.98); }
    100%{ transform:translateX(-50%) translateY(-9px) scale(1,1); }
  }
  .loading-wood{
    position:absolute; bottom:0; left:50%;
    width:150px; height:50px;
    transform:translateX(-50%);
    transform-origin:bottom center;
    z-index:1;
    animation:loadingWoodReact 1.4s cubic-bezier(.45,0,.55,1) infinite;
  }
  @keyframes loadingWoodReact{
    0%,50%{  transform:translateX(-50%) scale(1,1) rotate(0deg); }
    54%{ transform:translateX(-50%) scale(1.14,.7) rotate(-1.5deg); }
    62%{ transform:translateX(-50%) scale(.93,1.12) rotate(1.5deg); }
    75%{ transform:translateX(-50%) scale(1.02,.98) rotate(0deg); }
    100%{ transform:translateX(-50%) scale(1,1) rotate(0deg); }
