.tc-footer{ font-size:10.2px; color:#fff; opacity:.55; text-align:center; margin-top:10px; line-height:1.5; }

.switch{
  position:relative; display:inline-block; width:36px; height:20px; flex-shrink:0;
}
.switch input{ opacity:0; width:0; height:0; }
.switch .slider{
  position:absolute; cursor:pointer; inset:0;
  background:var(--paper-dim); border:2px solid var(--ink); border-radius:0;
  transition:background .15s ease; box-shadow:var(--pixel-shadow);
}
.switch .slider::before{
  content:""; position:absolute; width:12px; height:12px; left:2px; top:2px;
  background:var(--ink-soft); transition:transform .15s ease, background .15s ease;
}
.switch input:checked + .slider{ background:var(--sun-deep); border-color:var(--sun-deep); }
.switch input:checked + .slider::before{ transform:translateX(16px); background:var(--surface); }
.switch input:focus-visible + .slider{ outline:2px solid var(--profit); outline-offset:2px; }
.rcm-title-row{
  display:flex; align-items:center; gap:8px; flex-basis:100%;
}
.rcm-toggle-row{
  display:flex; align-items:center; gap:8px; margin-top:2px;
}
