.rcm-panel{
  margin-top:8px; border:2px solid var(--ink); box-shadow:var(--pixel-shadow);
  background:var(--paper-dim); padding:6px; border-radius:0;
}
.rcm-tabs{
  display:flex; gap:4px; overflow-x:auto; padding-bottom:6px; margin-bottom:6px;
  border-bottom:2px dashed var(--line);
}
.rcm-tab{
  flex:0 0 auto; font-family:var(--pixel-font); font-size:7.8px; letter-spacing:.3px;
  padding:6px 7px; background:transparent; color:var(--ink-soft);
  border:2px solid var(--line); border-radius:0; cursor:pointer;
  box-shadow:2px 2px 0 rgba(0,0,0,.18); transition:transform .1s ease;
  white-space:nowrap;
}
.rcm-tab:active{ transform:translate(1px,1px); box-shadow:1px 1px 0 rgba(0,0,0,.18); }
.rcm-tab.active{ background:var(--sun); color:var(--soil-dark); border-color:var(--soil-dark); }

.rcm-list{
  max-height:180px; overflow-y:auto; display:flex; flex-direction:column; gap:4px;
  padding-right:2px;
}
.rcm-item-row{
  display:flex; align-items:center; gap:7px; padding:5px 6px;
