}
.rcm-item-icon{ width:16px; height:16px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.rcm-item-name{ font-size:11.4px; font-weight:700; color:var(--ink); flex:1; }
.rcm-item-check{
  appearance:none; -webkit-appearance:none; width:16px; height:16px; flex-shrink:0;
  border:2px solid var(--ink); background:var(--paper-dim); cursor:pointer; position:relative;
  box-shadow:1.5px 1.5px 0 rgba(0,0,0,.25);
}
.rcm-item-check:checked{ background:var(--sun-deep); border-color:var(--soil-dark); }
.rcm-item-check:checked::after{
  content:"✓"; position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
  font-size:13.2px; font-weight:900; color:#fff; line-height:1;
}
.rcm-panel-footer{
  display:flex; align-items:center; justify-content:space-between; gap:8px; margin-top:8px;
  padding-top:6px; border-top:2px dashed var(--line);
}
.rcm-unsaved-note{ font-size:9px; color:var(--loss); font-weight:700; flex:1; }
.rcm-save-btn{ padding:7px 12px; font-size:10.8px; font-family:var(--pixel-font); letter-spacing:.4px; }
.rcm-excluded-tag{ color:var(--loss); font-weight:700; }

