.bl-summary-box{
  display:flex; gap:12px; align-items:flex-start; padding:10px;
  margin-bottom:10px; background:var(--parchment,#fdf3df);
  border:3px solid var(--soil-dark); border-radius:8px;
  box-shadow:3px 3px 0 rgba(0,0,0,.4), inset 0 0 0 2px rgba(255,255,255,.15);
}
.bl-summary-box .profile-bumpkin-frame{ width:96px; height:96px; margin:0; flex-shrink:0; }
.bl-summary-info{ flex:1; min-width:0; display:flex; flex-direction:column; gap:3px; }
.bl-summary-name{ font-family:var(--pixel-font); font-size:11.4px; font-weight:700; }
.bl-summary-level{ font-size:13.2px; font-weight:800; }
.bl-summary-xp{ display:block; font-size:10.2px; font-weight:600; opacity:.8; margin-top:2px; }
.bl-summary-line{
  display:flex; justify-content:space-between; gap:8px; font-size:10.2px;
  padding:3px 0; border-top:1px dashed var(--line); margin-top:2px;
}
.bl-summary-sub-label{ opacity:.75; }
.bl-summary-sub-value{ font-weight:700; text-align:right; }

.bl-levels-box{
  background:var(--wheat-dim,#f1e3c2); border:3px solid var(--soil-dark);
  border-radius:8px; padding:8px;
  box-shadow:3px 3px 0 rgba(0,0,0,.4), inset 0 0 0 2px rgba(255,255,255,.15);
}
.bl-section-caption{
  font-size:10.2px; font-weight:800; text-transform:uppercase;
  letter-spacing:.4px; opacity:.85; margin-bottom:6px;
}
.bl-picker-strip{ display:flex; flex-wrap:wrap; gap:4px; margin-bottom:8px; }
.bl-nav-tab{
  font-size:9.6px; font-family:inherit; padding:5px 8px; border-radius:6px;
  border:1.5px solid var(--line); background:var(--parchment,#fff);
  cursor:pointer; touch-action:manipulation;
}
.bl-nav-tab.active{ background:var(--sun-deep,#c98a3a); color:#fff; }

.bl-level-block{ display:none; }
.bl-block-title{
  font-family:var(--pixel-font); font-size:10.2px; font-weight:700;
  letter-spacing:.3px; margin:0 0 6px; padding:5px 7px;
  background:var(--wheat,#f5e6c8); border:1.5px solid var(--soil-dark);
}
.bl-level-block.active{ display:block; }

.bl-cols-head{
  display:grid; grid-template-columns:0.6fr 1.5fr 1fr 1.3fr; gap:4px;
  font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.3px;
  opacity:.75; padding:3px 6px;
}
.bl-list-wrap{ max-height:340px; overflow-y:auto; -webkit-overflow-scrolling:touch; overscroll-behavior:contain; }
.bl-level-row{
  display:grid; grid-template-columns:0.6fr 1.5fr 1fr 1.3fr; gap:4px;
  font-size:10.2px; font-weight:700; padding:4px 6px;
  border-bottom:1px solid var(--line);
}
.bl-level-row.is-done{ background:var(--wheat,#f5e6c8); }
.bl-cols-total{
  display:grid; grid-template-columns:0.6fr 1.5fr 1fr 1.3fr; gap:4px;
  font-size:10.2px; font-weight:800; padding:6px; margin-top:4px;
  border-top:2px solid var(--line);
}

@media (min-width:700px){
  .bl-levels-content{ display:flex; flex-wrap:wrap; gap:10px; }
  .bl-level-block{ display:block !important; flex:1 1 300px; min-width:270px; max-width:100%; }
}

