.feed-xp-chip {
  display: inline-block;
  margin: 0 4px 0 2px;
  padding: 1px 7px;
  border: 1.5px solid var(--sun-deep);
  border-radius: 6px;
  background: var(--paper-dim);
  color: var(--ink);
  font-size: 0.85em;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: none;
  vertical-align: middle;
  white-space: nowrap;
}

.animal-love {
  box-sizing: border-box;
  margin-bottom: 4px;
  padding: 8px 9px;
  border-radius: 7px;
  background: var(--parchment);
}

.animal-love .lib-section-title {
  margin: 0 0 6px;
  flex-wrap: wrap;
  gap: 2px 6px;
}

.animal-love-grid {
  display: flex;
  gap: 10px;
}

.animal-love-col {
  flex: 1;
  min-width: 0;
  font-size: 12.5px;
  line-height: 1.35;
}

.animal-love-name {
  color: var(--ink);
  font-weight: 700;
}

.animal-love-xp {
  color: var(--ink-soft);
  font-weight: 800;
  white-space: nowrap;
}

.animal-love-times {
  color: var(--ink-soft);
  font-weight: 800;
}

.animal-love-input {
  width: 52px;
  margin: 0 0 0 4px;
  padding: 2px 4px;
  border: 1.5px solid var(--ink);
  border-radius: 4px;
  outline: 0;
  box-shadow: none;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-weight: 800;
  text-align: center;
  -moz-appearance: textfield;
  appearance: textfield;
}

.animal-love-input::-webkit-outer-spin-button,
.animal-love-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.animal-love-input:disabled {
  opacity: 0.45;
}

.animal-love-col.is-off .animal-love-name,
.animal-love-col.is-off .animal-love-xp,
.animal-love-col.is-off .animal-love-total-label,
.animal-love-col.is-off .animal-love-total {
  opacity: 0.5;
}

.animal-love-total-label {
  margin-top: 4px;
  color: var(--ink-soft);
  font-size: 10.2px;
  font-weight: 600;
  line-height: 1.3;
}

.animal-love-total {
  color: var(--ink);
  font-weight: 800;
  white-space: nowrap;
}

body.sfl-theme .animal-love {
  position: relative !important;
  padding: 8px 9px !important;
