}

.lb-tabs{ display:flex; gap:4px; margin-bottom:10px; overflow-x:auto; }
.lb-tabs .market-tab-btn{ flex:0 0 auto; white-space:nowrap; }
.lb-columns{ display:flex; flex-direction:column; gap:12px; }
.lb-board{ display:none; flex-direction:column; }
.lb-board.lb-active{ display:flex; }
.lb-desc{ font-family:'JetBrains Mono',monospace; font-size:10.2px; opacity:.8; margin:0 0 8px; line-height:1.4; }
.lb-list{ display:flex; flex-direction:column; gap:6px; max-height:420px; overflow-y:auto; padding:0 4px 4px 0; }
.lb-row.cb-item{ flex-direction:row; align-items:center; gap:8px; padding:6px 8px; }
.lb-rank{ min-width:26px; font-size:11px; font-weight:800; text-align:right; }
.lb-name{ flex:1 1 auto; min-width:0; font-size:11.5px; font-weight:800; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.lb-lvl{ font-family:'JetBrains Mono',monospace; font-size:9.5px; opacity:.7; white-space:nowrap; }
.lb-count{ font-size:11px; font-weight:800; white-space:nowrap; }
.lb-empty{ font-family:'JetBrains Mono',monospace; font-size:10.5px; opacity:.75; padding:6px; }
@media (min-width:900px){
  .lb-tabs{ display:none; }
  .lb-columns{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); align-items:start; }
  .lb-board{ display:flex; }
}
