.map-scroll{ overflow:auto; max-width:100%; max-height:70vh; }
.map-grid{
  position:relative;
  background-image:linear-gradient(to right, rgba(0,0,0,.14) 1px, transparent 1px), linear-gradient(to bottom, rgba(0,0,0,.14) 1px, transparent 1px);
  background-size:var(--map-cell) var(--map-cell);
  background-position:var(--map-axis) var(--map-axis);
  background-repeat:repeat;
  image-rendering:pixelated;
}
.map-axis-x, .map-axis-y{
  position:absolute; display:flex; align-items:center; justify-content:center;
  font-family:'JetBrains Mono',monospace; font-size:9px; font-weight:800; opacity:.7;
}
.map-axis-x{ top:0; height:var(--map-axis); }
.map-axis-y{ left:0; }
.map-node{
  position:absolute; box-sizing:border-box; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:1px; overflow:hidden;
}
.map-node-badge, .map-node-yield{
  font-family:'JetBrains Mono',monospace; font-size:9px; font-weight:800; line-height:10px;
  min-height:10px; white-space:nowrap;
}
.map-node-badge{ min-width:12px; padding:0 3px; text-align:center; }
.map-node-badge.has-badge{ background:#8a8f98; color:#ffffff; border-radius:8px; }
.map-node-icon{ display:flex; align-items:center; justify-content:center; line-height:0; }
.map-node-yield.has-proc{ color:#1b7a3a; text-decoration:underline; }
.map-node-procs{ position:absolute; right:0; bottom:11px; display:flex; flex-direction:column; align-items:flex-end; gap:1px; pointer-events:none; }
.map-node-proc{
  font-family:'JetBrains Mono',monospace; font-size:7px; font-weight:800; line-height:8px;
  padding:0 2px; border-radius:3px; color:#fff; background:#1b7a3a;
}
.map-node-proc.proc-t{ background:#7a4a1b; }
.map-node-proc.proc-g{ background:#5a5a68; }
.map-node-proc.proc-r{ background:#1b5a8a; }
.map-node-proc.proc-p{ background:#8a1b4a; }
.map-node-proc.proc-c{ background:#a8322f; }
.map-node-pickable{ cursor:pointer; }
.map-node-picked{ outline:2px solid #1b7a3a; outline-offset:-2px; border-radius:6px; }
.map-node-pick{ position:absolute; left:0; bottom:11px; padding:0 3px; font-size:9px; line-height:12px; background:#1b7a3a; color:#ffffff; border-radius:6px; pointer-events:none; }
.map-node-auto{ background:#5a6678; }
.map-reset-order{ margin-top:6px; padding:4px 10px; font-size:12px; cursor:pointer; }

.map-guide{ margin:0 0 10px; padding:0; }
.map-guide-summary{
  list-style:none; cursor:pointer; display:flex; align-items:center; justify-content:space-between;
  padding:10px;
  font-family:var(--pixel-font); font-size:12.6px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; -webkit-tap-highlight-color:transparent;
}
.map-guide-summary::-webkit-details-marker{ display:none; }
.map-guide-summary::after{
  content:""; width:8px; height:8px; border-right:3px solid currentColor; border-bottom:3px solid currentColor;
  transform:rotate(45deg); margin:-4px 4px 0 0; transition:transform .2s ease; flex-shrink:0;
}
.map-guide[open] > .map-guide-summary::after{ transform:rotate(-135deg); margin:4px 4px 0 0; }
body.sfl-theme .map-guide-summary::after,
body.sfl-theme .map-guide[open] > .map-guide-summary::after{
  width:13px; height:19px; margin:0; border:none; transform:none; transition:none;
  background-image:var(--sfl-chevron-right); background-repeat:no-repeat;
  background-position:center; background-size:contain; image-rendering:pixelated;
}
body.sfl-theme .map-guide[open] > .map-guide-summary::after{
  background-image:var(--sfl-chevron-down);
}
.map-guide-body{
  padding:0 10px 10px;
  font-family:'JetBrains Mono',monospace; font-size:10.2px; line-height:1.4;
  animation:mapGuideSlide .22s ease-out;
}
.map-guide-body p{ margin:0 0 8px; opacity:.85; }
.map-guide-legend{ display:flex; flex-direction:column; gap:6px; margin:0 0 8px; }
.map-guide-item{
  display:flex; align-items:flex-start; gap:8px; padding:4px 6px;
  background:var(--wheat-dim);
}
body.sfl-theme .map-guide-item{ background:var(--sfl-outer); }
.map-guide-code{ position:static; flex:0 0 auto; text-align:center; margin-top:1px; }
.map-guide-text{ flex:1 1 auto; min-width:0; }
@keyframes mapGuideSlide{
  from{ opacity:0; transform:translateY(-6px); }
  to{ opacity:1; transform:translateY(0); }
}

